import crypto from "node:crypto";
import { decryptData, encryptData } from "../encryption.js";

const encryptionKey = Buffer.from(
  "ae18ad906ec2686f7cd8e3b9e97255f4d048225771c0412e82717256dc27c49a",
  "hex",
);

const falseEncryptionKey = Buffer.from(
  "ae18ad806ba2686f7cd8c7b9e97255f4d048225771c0412e82717256dc27c49a",
  "hex",
);

describe("state persistence encryption", () => {
  it("should encrypt data and return the encrypted content", () => {
    const encryptedData = encryptData(encryptionKey, "some string");

    expect(encryptedData.length).toBeGreaterThan(0);
  });

  it("should decrypt data and return the decrypted content", () => {
    const decryptedData = decryptData(
      encryptionKey,
      "",
    );

    expect(decryptedData).toEqual(
      '{"address":"2f7f9d626334e7f1d0ceea95565287f4256dad50599b929bbddc670fba70831c|0100008d9cf18b7b72d28aa7a35583f48ae3abec78db48fe87737e56318bd43eef80bf","availableBalance":"25000000000000000n","totalBalance":"25000000000000000n","availableCoins":["5000000000000000n","5000000000000000n","5000000000000000n","5000000000000000n","5000000000000000n"],"totalCoins":["5000000000000000n","5000000000000000n","5000000000000000n","5000000000000000n","5000000000000000n"],"syncProgress":{"synced":"9n","total":"9n"}}',
    );
  });

  it("throws when decrypting modified ciphertext", () => {
    expect(() =>
      decryptData(
        encryptionKey,
        "",
      ),
    ).toThrow();
  });

  it("throws when decrypting with wrong key", () => {
    expect(() =>
      decryptData(
        falseEncryptionKey,
        "",
      ),
    ).toThrow();
  });

  it("throws when decrypting truncated ciphertext", () => {
    expect(() =>
      decryptData(
        encryptionKey,
        "",
      ),
    ).toThrow();
  });

  it("throws when encrypting with invalid key length", () => {
    expect(() => encryptData(crypto.randomBytes(22), "some string")).toThrow();
  });
});
